package com.transithub.shared.id;

import java.security.SecureRandom;
import java.util.UUID;

/**
 * Generates time-ordered UUIDs (version 7, RFC 9562).
 *
 * <p>All TransitHub identifiers are generated by the application or the
 * offline device, never by the database (ADR-0005), so records can be
 * created without connectivity. Version 7 puts a millisecond timestamp in
 * the most significant bits, so identifiers sort roughly by creation time
 * and stay index-friendly.
 *
 * <p>Within one JVM, identifiers are strictly increasing: if two are created
 * in the same millisecond (or the clock moves backwards), the 12-bit
 * sub-millisecond counter is incremented instead.
 */
public final class UuidV7 {

    private static final SecureRandom RANDOM = new SecureRandom();

    private static final Object LOCK = new Object();
    private static long lastTimestamp = -1L;
    private static int counter;

    private UuidV7() {
    }

    public static UUID generate() {
        long timestamp;
        int sequence;

        synchronized (LOCK) {
            long now = System.currentTimeMillis();

            if (now > lastTimestamp) {
                lastTimestamp = now;
                counter = RANDOM.nextInt(1 << 11); // leave room to increment
            } else {
                counter++;
                if (counter > 0xFFF) {
                    lastTimestamp++;              // borrow the next millisecond
                    counter = 0;
                }
            }

            timestamp = lastTimestamp;
            sequence = counter;
        }

        long mostSignificant = (timestamp << 16)
                | (0x7L << 12)                    // version 7
                | (sequence & 0xFFFL);

        long leastSignificant = (RANDOM.nextLong() & 0x3FFFFFFFFFFFFFFFL)
                | 0x8000000000000000L;           // IETF variant (10xx)

        return new UUID(mostSignificant, leastSignificant);
    }

    /** Millisecond Unix timestamp embedded in a version 7 UUID. */
    public static long timestampOf(UUID uuid) {
        if (uuid.version() != 7) {
            throw new IllegalArgumentException("Not a version 7 UUID: " + uuid);
        }
        return uuid.getMostSignificantBits() >>> 16;
    }
}
